@RestControllerAdvice
public class GlobalExceptionHandler {
  @ExceptionHandler(MethodArgumentNotValidException.class)
  @ResponseStatus(HttpStatus.BAD_REQUEST)
  public ApiResponse<Void> onInvalid(MethodArgumentNotValidException e) {
    String msg = e.getBindingResult().getFieldErrors().stream()
        .map(f -> f.getField() + " " + f.getDefaultMessage())
        .findFirst().orElse("参数不合法");
    return ApiResponse.fail(40000, msg);
  }

  @ExceptionHandler(Exception.class)
  @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
  public ApiResponse<Void> onOther(Exception e) {
    String traceId = UUID.randomUUID().toString().substring(0, 8);
    log.error("unhandled error traceId={}", traceId, e);
    return ApiResponse.fail(50000, "服务异常，请稍后重试（" + traceId + "）");
  }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {
  private final JwtAuthFilter jwtAuthFilter;

  @Bean
  SecurityFilterChain chain(HttpSecurity http) throws Exception {
    http.csrf(AbstractHttpConfigurer::disable)
        .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .authorizeHttpRequests(a -> a
            .requestMatchers("/api/auth/**", "/api/ping").permitAll()
            .anyRequest().authenticated())
        .exceptionHandling(e -> e.authenticationEntryPoint((req, res, ex) -> {
            res.setStatus(401);
            res.setContentType("application/json;charset=UTF-8");
            res.getWriter().write("{\"code\":40100,\"msg\":\"未登录或凭证已过期\"}");
        }))
        .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
    return http.build();
  }

  @Bean PasswordEncoder passwordEncoder() { return new BCryptPasswordEncoder(); }
}

@Service
public class JwtService {
  private final SecretKey key;
  private final Duration accessTtl;

  public JwtService(@Value("${jwt.secret}") String secret,
                    @Value("${jwt.access-ttl}") Duration accessTtl) {
    this.key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    this.accessTtl = accessTtl;
  }

  public String issue(long userId, String role) {
    Instant now = Instant.now();
    return Jwts.builder().subject(String.valueOf(userId)).claim("role", role)
        .issuedAt(Date.from(now)).expiration(Date.from(now.plus(accessTtl)))
        .signWith(key).compact();
  }

  public Jws<Claims> parse(String token) {
    return Jwts.parser().verifyWith(key).build().parseSignedClaims(token);
  }
}

@Component
public class JwtAuthFilter extends OncePerRequestFilter {
  private final JwtService jwt;

  @Override
  protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
      throws ServletException, IOException {
    String h = req.getHeader("Authorization");
    if (h != null && h.startsWith("Bearer ")) {
      try {
        Claims c = jwt.parse(h.substring(7)).getPayload();
        var auth = new UsernamePasswordAuthenticationToken(
            Long.valueOf(c.getSubject()), null,
            List.of(new SimpleGrantedAuthority("ROLE_" + c.get("role", String.class))));
        SecurityContextHolder.getContext().setAuthentication(auth);
      } catch (JwtException | IllegalArgumentException ignored) {
        SecurityContextHolder.clearContext();
      }
    }
    chain.doFilter(req, res);
  }
}

@RestController
@RequestMapping("/api/auth")
public class AuthController {
  @PostMapping("/login")
  public ApiResponse<TokenRes> login(@Valid @RequestBody LoginReq req, HttpServletResponse res) {
    User u = userService.verify(req.username(), req.password()); // 抛 401
    String access = jwt.issue(u.id(), u.role());
    String refresh = refreshService.issue(u.id());
    res.addHeader(HttpHeaders.SET_COOKIE, cookie(refresh).toString());
    return ApiResponse.ok(new TokenRes(access, u.name()));
  }

  @PostMapping("/refresh")
  public ApiResponse<TokenRes> refresh(@CookieValue(name = "rt", required = false) String rt) {
    Long uid = refreshService.rotate(rt); // 旧 token 立即失效
    return ApiResponse.ok(new TokenRes(jwt.issue(uid, "USER"), null));
  }

  private ResponseCookie cookie(String v) {
    return ResponseCookie.from("rt", v).httpOnly(true).secure(true)
        .sameSite("Lax").path("/api/auth").maxAge(Duration.ofDays(7)).build();
  }
}

@RestController
@RequestMapping("/api/tasks")
public class TaskController {
  @GetMapping
  public ApiResponse<PageRes<TaskDto>> page(@RequestParam(defaultValue = "0") int page,
                                            @RequestParam(defaultValue = "20") int size,
                                            @RequestParam(required = false) String kw,
                                            @AuthenticationPrincipal Long uid) {
    int safeSize = Math.min(Math.max(size, 1), 100);
    return ApiResponse.ok(service.page(uid, page, safeSize, kw));
  }

  @PostMapping
  public ApiResponse<TaskDto> create(@Valid @RequestBody TaskReq req, @AuthenticationPrincipal Long uid) {
    return ApiResponse.ok(service.create(uid, req)); // ownerId 只来自 token
  }
}

@Service
@RequiredArgsConstructor
public class TaskService {
  private final TaskRepo repo;

  public PageRes<TaskDto> page(long uid, int page, int size, String kw) {
    Pageable p = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "createdAt", "id"));
    Page<Task> res = (kw == null || kw.isBlank())
        ? repo.findByOwnerId(uid, p)
        : repo.findByOwnerIdAndTitleContaining(uid, kw.trim(), p);
    return new PageRes<>(res.map(TaskDto::of).getContent(), res.getTotalElements(), page, size);
  }

  public TaskDto create(long uid, TaskReq req) {
    Task t = new Task(null, uid, req.title(), "TODO", Instant.now());
    return TaskDto.of(repo.save(t));
  }
}

@Service
public class StorageService {
  private static final Set<String> OK = Set.of("jpg", "jpeg", "png", "webp");

  @Value("${upload.dir}") String dir;

  public String save(MultipartFile f) throws IOException {
    String name = Optional.ofNullable(f.getOriginalFilename()).orElse("");
    String ext = name.contains(".") ? name.substring(name.lastIndexOf('.') + 1).toLowerCase() : "";
    if (!OK.contains(ext)) throw new BizException(40001, "只允许 jpg/png/webp");
    String key = UUID.randomUUID().toString().replace("-", "") + "." + ext;
    Path target = Paths.get(dir).toAbsolutePath().normalize().resolve(key);
    Files.createDirectories(target.getParent());
    try (InputStream in = f.getInputStream()) { Files.copy(in, target); }
    return "/uploads/" + key;
  }
}

