import axios from 'axios'

export const http = axios.create({ baseURL: '/api', timeout: 15000 })
let refreshing: Promise<string> | null = null

http.interceptors.request.use((cfg) => {
  const t = useAuthStore().access
  if (t) cfg.headers.Authorization = `Bearer ${t}`
  return cfg
})

http.interceptors.response.use(
  (r) => r.data.data,
  async (err) => {
    const cfg = err.config ?? {}
    const status = err.response?.status
    if (status === 401 && !cfg._retry && !cfg.url?.includes('/auth/')) {
      cfg._retry = true
      refreshing ??= authApi.refresh().finally(() => { refreshing = null })
      try {
        const token = await refreshing
        useAuthStore().setAccess(token)
        cfg.headers.Authorization = `Bearer ${token}`
        return http(cfg)
      } catch {
        useAuthStore().logout()
        router.push({ path: '/login', query: { redirect: location.pathname } })
      }
    }
    return Promise.reject({ code: err.response?.data?.code ?? -1, msg: err.response?.data?.msg ?? '网络异常' })
  }
)

const router = createRouter({
  history: createWebHistory(),
  routes: [
    { path: '/login', component: () => import('@/pages/LoginView.vue') },
    { path: '/tasks', component: () => import('@/pages/TaskListView.vue'), meta: { auth: true } },
    { path: '/:pathMatch(.*)*', component: () => import('@/pages/NotFound.vue') }
  ]
})

router.beforeEach((to) => {
  const auth = useAuthStore()
  if (to.meta.auth && !auth.access) {
    return { path: '/login', query: { redirect: to.fullPath } }
  }
  if (to.path === '/login' && auth.access) return { path: '/tasks' }
})

export const useAuthStore = defineStore('auth', () => {
  const access = ref('')
  const name = ref('')
  const isLogin = computed(() => !!access.value)

  function setAccess(t: string) { access.value = t }
  async function login(u: string, p: string) {
    const r = await authApi.login(u, p)
    access.value = r.token
    name.value = r.name ?? ''
  }
  async function logout() {
    await authApi.logout().catch(() => {})
    access.value = ''
    name.value = ''
  }
  return { access, name, isLogin, setAccess, login, logout }
})

